"""Original MIT Z80 FM/PSG setup for the original Philips/SCC-I diagnostics.
No proprietary firmware or audio inputs. Run from the repository root.
"""
from pathlib import Path
root=Path(__file__).parent
rom=bytearray([255])*16384
for line in (root/'philips-disk.hex').read_text().splitlines():
    if line.startswith('#'): continue
    offset,data=line.split(':')
    data=bytes.fromhex(data)
    start=int(offset,16)
    rom[start:start+len(data)]=data
rom[2:4]=bytes([0,0x45])
code=[]
def out(port,value): code.extend([0x3e,value,0xd3,port])
for reg,value in list(enumerate([0x21,0x21,0x3f,0,0,0xf0,0,0x0f]))+[(0x30,0),(0x10,0x22),(0x20,0x19)]:
    out(0x7c,reg);code.extend([0,0]);out(0x7d,value);code.extend([0]*18)
for reg,value in [(0,100),(1,0),(7,0x3e),(8,15)]:
    out(0xa0,reg);out(0xa1,value)
code.extend([0xc3,0,0x41]) # original Philips fixture init
rom[0x500:0x500+len(code)]=bytes(code)
lines=['# Original MIT Z80 diagnostic. Generated by music-disk.py from original philips-disk.hex.']
for start in range(0,len(rom),16):
    data=rom[start:start+16]
    if data!=bytes([255])*16: lines.append(f'{start:04x}: '+data.hex(' '))
(root/'music-disk.hex').write_text('\n'.join(lines)+'\n')
